            color=grid[r][c]
            if color==max(Counter(v for row in grid for v in row), key=Counter(v for row in grid for v in row).get) or (r,c) in seen:
                continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append((color,cells))
    return out

def _corner(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    # A filled L: a full outer row and a full perpendicular edge, with no interior pixels.
    s={(r-r0,c-c0) for r,c in cells}; H=r1-r0+1; W=c1-c0+1
    for rr in (0,H-1):
        for cc in (0,W-1):
            row={(rr,x) for x in range(W)}; col={(y,cc) for y in range(H)}
            if s==row|col:
                return (rr,cc)
    return None

def transform(grid):
    g=[row[:] for row in grid]
