    for color,cells in comps:
        corner=_corner(cells)
        if corner is not None:
            lcomps.append((color,cells,corner))
    # The small L gives the recolor; recolor the other L with the same orientation.
    refs=[x for x in lcomps if x[0]!=bg and len(x[1])<=4]
    for ref in refs:
        color,cells,corner=ref
        candidates=[x for x in lcomps if x[0]!=bg and x[0]!=color and x[2]==corner]
        if candidates:
            target=max(candidates,key=lambda x:len(x[1]))
            for r,c in target[1]: g[r][c]=color
            return g
    # For the task's larger-scale examples, the border L is the color source.
